sinch.sms.body_template:
{% if event.type == "sms.inbound" %}{
  "type": "mo_text",
  "id": "{{ data.provider_id }}",
  "from": "{{ data.from_number }}",
  "to": "{{ data.to_number }}",
  "body": "{{ data.body }}",
  "received_at": "{{ event.created_at }}"
}{% else %}{
  "type": "recipient_delivery_report_sms",
  "batch_id": "{{ data.provider_id }}",
  "recipient": "{{ data.to_number }}",
  "code": 0,
  "status": "{% if data.status == "delivered" %}Delivered{% else %}{% if data.status == "failed" %}Failed{% else %}{% if data.status == "undelivered" %}Rejected{% else %}Dispatched{% endif %}{% endif %}{% endif %}",
  "at": "{{ event.created_at }}"
}{% endif %}

infobip.dlr.body_template:
{
  "results": [
    {
      "messageId": "{{ data.provider_id }}",
      "to": "{{ data.to_number }}",
      "sentAt": "{{ event.created_at }}",
      "doneAt": "{{ event.created_at }}",
      "smsCount": 1,
      "status": { "groupId": 3, "groupName": "{% if data.status == "delivered" %}DELIVERED{% else %}{% if data.status == "failed" %}UNDELIVERABLE{% else %}{% if data.status == "undelivered" %}REJECTED{% else %}PENDING{% endif %}{% endif %}{% endif %}", "id": 5, "name": "{% if data.status == "delivered" %}DELIVERED{% else %}{% if data.status == "failed" %}UNDELIVERABLE{% else %}{% if data.status == "undelivered" %}REJECTED{% else %}PENDING{% endif %}{% endif %}{% endif %}", "description": "Message status from SendMock" },
      "error": { "groupId": 0, "groupName": "OK", "id": 0, "name": "NO_ERROR", "description": "No Error", "permanent": false }
    }
  ]
}

telnyx.message.body_template:
{
  "data": {
    "event_type": "{% if event.type == "sms.inbound" %}message.received{% else %}{% if data.status == "sent" %}message.sent{% else %}message.finalized{% endif %}{% endif %}",
    "id": "{{ uuid() }}",
    "occurred_at": "{{ event.created_at }}",
    "record_type": "event",
    "payload": {
      "id": "{{ data.provider_id }}",
      "record_type": "message",
      "direction": "{% if event.type == "sms.inbound" %}inbound{% else %}outbound{% endif %}",
      "type": "SMS",
      "from": { "phone_number": "{{ data.from_number }}" },
      "to": [{ "phone_number": "{{ data.to_number }}"{% if event.type == "sms.status" %}, "status": "{{ data.status }}"{% endif %} }],
      "text": "{{ data.body }}",
      "errors": []
    }
  },
  "meta": { "attempt": 1 }
}

mailgun.events.body_template:
{% set mailgun_timestamp = event.created_at | unix %}{% set mailgun_token = random_hex(50) %}{
  "signature": {
    "timestamp": "{{ mailgun_timestamp }}",
    "token": "{{ mailgun_token }}",
    "signature": "{{ mailgun_signature(vars.mailgun_signing_key, mailgun_timestamp, mailgun_token) }}"
  },
  "event-data": {
    "id": "{{ event.id }}",
    "timestamp": {{ mailgun_timestamp }},
    "event": "{{ event.type | mailgun_event }}",
    "recipient": "{{ data.to[0].address }}",{% if event.type == "email.clicked" %}
    "url": "{{ data.url }}",{% endif %}
    "message": {
      "headers": {
        "message-id": "{{ data.message_id | default(data.id) }}",
        "from": "{{ data.from.address }}",
        "to": "{{ data.to[0].address }}",
        "subject": "{{ data.subject }}"
      }
    }
  }
}

sparkpost.events.body_template:
[
  {
    "msys": {
      "{% if event.type == "email.clicked" %}track_event{% else %}{% if event.type == "email.opened" %}track_event{% else %}message_event{% endif %}{% endif %}": {
        "type": "{{ event.type | sendgrid_event }}",
        "event_id": "{{ event.id }}",
        "message_id": "{{ data.message_id | default(data.id) }}",
        "rcpt_to": "{{ data.to[0].address }}",
        "friendly_from": "{{ data.from.address }}",
        "subject": "{{ data.subject }}",
        "timestamp": "{{ event.created_at | unix }}"{% if event.type == "email.clicked" %},
        "target_link_url": "{{ data.url }}"{% endif %}
      }
    }
  }
]

sendgrid.events.body_template:
[
  {
    "email": "{{ data.to[0].address }}",
    "timestamp": {{ event.created_at | unix }},
    "smtp-id": "<{{ data.message_id | default(data.id) }}>",
    "event": "{{ event.type | sendgrid_event }}",{% if event.type == "email.clicked" %}
    "url": "{{ data.url }}",
    "url_offset": { "index": 0, "type": "html" },{% endif %}
    "category": [],
    "sg_event_id": "{{ event.id }}",
    "sg_message_id": "{{ data.message_id | default(data.id) }}.filter0001.1-1"
  }
]

resend.events.body_template:
{
  "type": "{{ event.type | resend_type }}",
  "created_at": "{{ event.created_at }}",
  "data": {
    "created_at": "{{ event.created_at }}",
    "email_id": "{{ data.message_id | default(data.id) }}",
    "from": "{{ data.from.address }}",
    "to": ["{{ data.to[0].address }}"],
    "subject": "{{ data.subject }}"{% if event.type == "email.clicked" %},
    "click": {
      "ipAddress": "127.0.0.1",
      "link": "{{ data.url }}",
      "timestamp": "{{ data.clicked_at }}",
      "userAgent": "{% if data.user_agent %}{{ data.user_agent }}{% endif %}"
    }{% endif %}
  }
}

slack.incoming_webhook.body_template:
{
  "text": "New {{ event.type }}: {{ data.subject | default(data.body) }}",
